initialize:
// Advisory PID tuner configuration. Runs on deploy (and on every restart) before
// any message arrives, so every other node can assume it exists.
flow.set('cfg', {
    // --- endpoints ---------------------------------------------------------
    stillBase: 'http://still2.mianos.com',
    llmUrl: 'http://docker-host.mianos.com:8082/v1/chat/completions',
    llmModel: 'LiquidAI/LFM2.5-24B-A2B-GGUF',

    // --- safety ------------------------------------------------------------
    dryRun: true,             // true = never POST /pid, only log what it would do
    maxDeltaPct: 30,          // max % change per gain, per proposal
    minProposalGapMin: 5,     // minimum spacing between LLM calls
    revertAfterMin: 15,       // watchdog horizon after an apply
    maxSetPointStep: 0.5,     // degC per proposal
    llmTimeoutMs: 90000,

    // --- digest ------------------------------------------------------------
    windowMin: 10,            // analysis window
    csvRows: 50,              // downsampled telemetry rows sent to the model
    maxSampleAgeSec: 30,      // refuse stale telemetry (e.g. a retained message)
    maxTokens: 500,

    // --- watchdog ----------------------------------------------------------
    watchdogWorsePct: 25,     // revert if mae worsens by this much
    watchdogBiasMargin: 0.3,  // degC of extra bias tolerated
    watchdogSatPct: 40,       // revert if this share of samples is saturated

    // --- hard envelope: mirror of PIDController + README. The LLM may never
    // leave it, whatever it argues; the validator drops the whole proposal.
    limits: {
        kp: [0, 8], ki: [0, 1], kd: [0, 60],
        set_point: [70, 85], output_min: [0, 50], output_max: [20, 100],
        integral_limit: [0, 10000], wind_down_threshold: [0, 10],
        integral_unwind_factor: [0, 0.9], derivative_filter: [0, 0.9]
    }
});
if (!Array.isArray(flow.get('buf'))) flow.set('buf', []);

func:
// Keep a bounded ring of PID telemetry for the digest. `received` is our own
// clock: a retained tele message from a previous session can be days old, and
// the digest must reject it rather than describe it as current.
const buf = flow.get('buf') || [];
const p = msg.payload || {};
const rec = { received: Date.now() };

if (p.fault === true) {
    rec.fault = true;
    rec.fail_safe = p.fail_safe === true;
    rec.held_output = p.held_output;
} else if (typeof p.current_temp === 'number' && isFinite(p.current_temp)) {
    rec.temp = p.current_temp;
    rec.sp = typeof p.set_point === 'number' ? p.set_point : null;
    rec.out = typeof p.output === 'number' ? p.output : null;
    rec.P = p.P; rec.I = p.I; rec.D = p.D;
    rec.integral = typeof p.integral === 'number' ? p.integral : null;
    rec.saturated = p.saturated === true;
    rec.emulation = p.emulation === true;
    rec.pump_ok = p.pump_ok !== false;
    rec.pump_stalled = p.pump_stalled === true;
} else {
    return null;   // unrecognised frame
}

buf.push(rec);
while (buf.length > 2000) buf.shift();
flow.set('buf', buf);
return null;

// Build the digest and the LLM request. Authoritative state comes from GET /pid;
// the time series comes from the local buffer. Anything ambiguous (stale,
// emulated, faulted, stopped, rate-limited) is refused here rather than
// described to the model as if it were a tuning problem.
const cfg = flow.get('cfg');
const say = t => ({ payload: 'digest refused: ' + t });
if (!cfg) return [null, say('CONFIG has not run: redeploy the flow')];

const snap = msg.payload || {};
if (typeof snap.kp !== 'number') return [null, say('GET /pid returned no parameters - device down?')];
const gapMin = cfg.minProposalGapMin;
if (Date.now() - (flow.get('lastAskAt') || 0) < gapMin * 60000)
    return [null, say('rate limit: one proposal per ' + gapMin + ' min')];
if (!snap.running) return [null, say('PID loop is stopped (POST /pid/run first) - nothing to tune')];
if (snap.emulation) return [null, say('emulation is on: current_temp is synthetic, not tunable')];

const now = Date.now();
const all = (flow.get('buf') || []).filter(s => s.received >= now - cfg.windowMin * 60000);
if (all.some(s => s.fault)) return [null, say('sensor fault inside the window - fix the sensor first')];
const buf = all.filter(s => typeof s.temp === 'number');
if (buf.length < 5)
    return [null, say('only ' + buf.length + ' samples in the last ' + cfg.windowMin + ' min (need 5)')];
const newest = buf[buf.length - 1];
const ageS = (now - newest.received) / 1000;
if (ageS > cfg.maxSampleAgeSec)
    return [null, say('newest sample is ' + ageS.toFixed(0) + ' s old (limit ' + cfg.maxSampleAgeSec + ' s)')];
if (buf.some(s => s.emulation)) return [null, say('emulation appeared inside the window')];
if (buf.some(s => s.pump_stalled))
    return [null, say('pump stall inside the window - fix the pump before tuning')];

const mean = a => a.reduce((x, y) => x + y, 0) / a.length;
const sp = typeof snap.set_point === 'number' ? snap.set_point : newest.sp;
const errs = buf.map(s => s.temp - (typeof s.sp === 'number' ? s.sp : sp));
const outs = buf.map(s => (typeof s.out === 'number' ? s.out : 0));
const bias = mean(errs);
let reversals = 0;
for (let i = 2; i < buf.length; i++) {
    const a1 = buf[i - 1].temp - buf[i - 2].temp;
    const a2 = buf[i].temp - buf[i - 1].temp;
    if (a1 * a2 < 0) reversals++;
}
const m = {
    n: buf.length,
    window_min: cfg.windowMin,
    sample_time_s: snap.sample_time,
    set_point: sp,
    temp_mean: +mean(buf.map(s => s.temp)).toFixed(3),
    bias: +bias.toFixed(3),                 // mean(temp - sp): + means running hot
    mae: +mean(errs.map(e => Math.abs(e))).toFixed(3),
    stddev: +Math.sqrt(mean(errs.map(e => (e - bias) * (e - bias)))).toFixed(3),
    temp_reversals_per_min: +(reversals / cfg.windowMin).toFixed(1),
    duty_mean: +mean(outs).toFixed(1),
    duty_max: +Math.max.apply(null, outs).toFixed(1),
    saturation_pct: +(100 * buf.filter(s => s.saturated).length / buf.length).toFixed(1),
    integral_peak: +Math.max.apply(null, buf.map(s => Math.abs(s.integral || 0))).toFixed(1)
};

const step = Math.max(1, Math.floor(buf.length / cfg.csvRows));
const rows = [];
for (let i = 0; i < buf.length; i += step) {
    const s = buf[i];
    rows.push([
        ((s.received - now) / 60000).toFixed(1),
        s.temp.toFixed(2),
        (typeof s.out === 'number' ? s.out : 0).toFixed(1),
        (s.P || 0).toFixed(2),
        (s.I || 0).toFixed(2),
        (s.D || 0).toFixed(2),
        s.saturated ? 1 : 0
    ].join(','));
}

// Stable prefix: identical bytes on every call is what makes the wrapper's
// prefix cache hit (cold ~20-40 s, warm ~2-3 s). Keep it free of run data.
const SYSTEM = [
'You are a control engineer assisting with a reflux distillation still. You never',
'touch hardware: you return a tuning proposal that a human reviews and that a',
'deterministic validator checks against a hard envelope.',
'',
'PLANT',
'- A PID runs every `sample_time` seconds on `current_temp`: vapour temperature at',
'  the head (top) of the column, degC.',
'- Output is reflux pump duty, percent 0..100 = coolant flow to the dephlegmator.',
'  More coolant means a cooler column.',
'- Direct acting on a cooling actuator: error = measurement - set_point, so output',
'  rises when the column is hotter than the setpoint.',
'- Setpoint is about 78.4 degC, the ethanol/water azeotrope vapour temperature.',
'  Hotter pushes water and heads through (product quality loss); colder floods the',
'  column and stops take-off. A setpoint change needs a process reason, not tuning.',
'- Expect large dead time: the pump responds in about 1 s, the column lags by tens',
'  of seconds to minutes.',
'',
'PARAMETERS (duty-percent units)',
'- kp  proportional gain, duty per degC of error.',
'- ki  integral gain per second; the integral state is bounded to +-integral_limit.',
'- kd  derivative gain per (degC/s) on the MEASUREMENT (no setpoint kick),',
'  EMA-filtered by derivative_filter (0 = off, 0.3..0.6 damps a noisy signal).',
'- integral_limit  hard bound on |I|.',
'- wind_down_threshold  below this |error| the integral leaks at',
'  integral_unwind_factor per second (0 disables the leak).',
'- output_min/output_max  duty clamp; output_min > 0 keeps the pump turning.',
'- Anti-windup is back-calculation against the output rail. Known artefact: while',
'  the output is pinned at output_min the integrator is preloaded towards',
'  (u_sat - P - D)/ki, so a small residual bias just after a cold start is',
'  expected and is not evidence of windup.',
'',
'HOW TO REASON',
'- Running hot and not saturated: raise kp (or ki) modestly.',
'- Slow return to setpoint after a disturbance: ki too low.',
'- Oscillation or jittery duty: kd too high for the sensor noise, or',
'  derivative_filter too low. Check temp_reversals_per_min first.',
'- Pinned at a rail for much of the window: the loop is authority-limited, not',
'  gain-limited. Say so instead of raising gains.',
'- integral_peak near integral_limit: windup risk; consider lowering the limit.',
'- Under about 10 minutes of data, or a fault/emulation/stall flag: the evidence is',
'  insufficient. Set confidence "low" and change nothing else.',
'- bias is mean(temp - sp) (positive = running hot), mae is mean |error|,',
'  saturation_pct is the share of samples pinned at a rail.',
'',
'RULES',
'- Change as few parameters as possible: one change per proposal, the smallest',
'  step the evidence supports.',
'- Never propose anything outside the hard envelope; the validator drops the whole',
'  proposal and the human sees nothing.',
'- Numbers must be finite JSON numbers, never strings.',
'',
'OUTPUT: one JSON object, no prose, no markdown fence:',
'{"diagnosis":"1-2 sentences on what the data shows",',
' "proposal":{"kp":2.0},',
' "expected_effect":"what should measurably change, and by when",',
' "confidence":"low|medium|high",',
' "watch_for":"the symptom that would mean this was wrong",',
' "revert_after_min":15}'
].join('\n');

const params = {
    kp: snap.kp, ki: snap.ki, kd: snap.kd, set_point: snap.set_point,
    output_min: snap.output_min, output_max: snap.output_max,
    integral_limit: snap.integral_limit,
    wind_down_threshold: snap.wind_down_threshold,
    integral_unwind_factor: snap.integral_unwind_factor,
    derivative_filter: snap.derivative_filter
};
const env = Object.keys(cfg.limits).map(function (k) {
    const b = cfg.limits[k];
    return k + ' ' + b[0] + '..' + b[1];
}).join(', ');

const req = {
    model: cfg.llmModel,
    temperature: 0,
    seed: 42,
    max_tokens: cfg.maxTokens,
    messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content:
            'HARD ENVELOPE (the validator rejects anything outside it): ' + env +
            '\n\nCURRENT PARAMETERS\n' + JSON.stringify(params, null, 1) +
            '\n\nMETRICS, LAST ' + m.window_min + ' MIN\n' + JSON.stringify(m, null, 1) +
            '\n\nTELEMETRY, one row every ' + step + ' loop ticks, newest row last\n' +
            't_min,temp_c,duty_pct,P,I,D,sat\n' + rows.join('\n') +
            '\n\nReply with the JSON object only.' }
    ]
};

flow.set('snapshot', snap);
flow.set('digest', { metrics: m, params: params, at: now });
flow.set('lastAskAt', now);
flow.set('lastRequest', req);
flow.set('retried', false);

msg.payload = req;
msg.headers = { 'Content-Type': 'application/json' };
msg.requestTimeout = cfg.llmTimeoutMs;
return [msg, null];

// Validate the model's reply. This is the trust boundary: the LLM proposes, this
// code disposes. Outputs: 1 = table, 2 = diagnosis, 3 = rejected, 4 = retry.
const cfg = flow.get('cfg');
const snap = flow.get('snapshot') || {};
const out2 = t => ({ payload: 'proposal rejected: ' + t });
const reject = why => {
    flow.set('proposal', { accepted: false, why: why, at: Date.now() });
    return [null, null, out2(why), null];
};
if (!cfg) return reject('CONFIG has not run: redeploy the flow');

const choice = (msg.payload && msg.payload.choices && msg.payload.choices[0]) || {};
const text = (choice.message && choice.message.content) || '';
const retryOrReject = why => {
    if (flow.get('retried')) return reject('after one retry: ' + why);
    const req = JSON.parse(JSON.stringify(flow.get('lastRequest') || {}));
    req.messages = (req.messages || []).concat([{ role: 'user', content:
        'That reply could not be used (' + why + '). Reply with the JSON object only, nothing else.' }]);
    flow.set('retried', true);
    msg.payload = req;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.requestTimeout = cfg.llmTimeoutMs;
    return [null, null, null, msg];
};

if (!text) return retryOrReject('empty reply');
if (choice.finish_reason === 'length') return reject('model hit max_tokens before finishing');
if (choice.finish_reason === 'tool_calls') return retryOrReject('reply was a tool call, not a proposal');

const body = String(text).trim().replace(/^```[a-zA-Z]*\n?/, '').replace(/```$/, '').trim();
const a = body.indexOf('{');
const b = body.lastIndexOf('}');
if (a < 0 || b <= a) return retryOrReject('no JSON object in the reply');
let parsed;
try {
    parsed = JSON.parse(body.slice(a, b + 1));
} catch (e) {
    return retryOrReject('invalid JSON: ' + e.message);
}

const raw = (parsed && typeof parsed.proposal === 'object' && parsed.proposal !== null)
    ? parsed.proposal : parsed;
const fields = Object.keys(cfg.limits);
const problems = [];
const clean = {};
for (let i = 0; i < fields.length; i++) {
    const f = fields[i];
    if (raw[f] === undefined || raw[f] === null) continue;
    const v = Number(raw[f]);
    if (!isFinite(v)) { problems.push(f + ' is not a finite number'); continue; }
    const lo = cfg.limits[f][0];
    const hi = cfg.limits[f][1];
    if (v < lo || v > hi) {
        problems.push(f + '=' + v + ' outside the envelope ' + lo + '..' + hi);
        continue;
    }
    clean[f] = v;
}
if (!Object.keys(clean).length) problems.push('no usable parameter in the proposal');
if (clean.output_min !== undefined && clean.output_max !== undefined && clean.output_min > clean.output_max)
    problems.push('output_min > output_max');
for (let i = 0; i < 3; i++) {
    const f = ['kp', 'ki', 'kd'][i];
    if (clean[f] === undefined) continue;
    const old = Number(snap[f]);
    if (!isFinite(old)) continue;
    const pct = Math.abs(clean[f] - old) / Math.max(Math.abs(old), 0.01) * 100;
    if (pct > cfg.maxDeltaPct)
        problems.push(f + ' would move ' + pct.toFixed(0) + '% (cap ' + cfg.maxDeltaPct + '%)');
}
if (clean.set_point !== undefined) {
    const d = Math.abs(clean.set_point - Number(snap.set_point));
    if (!(d <= cfg.maxSetPointStep))
        problems.push('set_point would move ' + d.toFixed(2) + ' degC (cap ' + cfg.maxSetPointStep + ')');
}
if (problems.length) return reject(problems.join('; '));

const proposal = {
    accepted: true, at: Date.now(), clean: clean,
    diagnosis: String(parsed.diagnosis || ''),
    confidence: String(parsed.confidence || 'low'),
    expected_effect: String(parsed.expected_effect || ''),
    watch_for: String(parsed.watch_for || ''),
    revert_after_min: Number(parsed.revert_after_min) > 0 ? Number(parsed.revert_after_min) : cfg.revertAfterMin,
    before: snap, model: cfg.llmModel,
    metrics: (flow.get('digest') || {}).metrics || null
};
flow.set('proposal', proposal);

const rows = Object.keys(clean).map(function (f) {
    const cur = Number(snap[f]);
    const pct = isFinite(cur) && cur !== 0 ? +(100 * (clean[f] - cur) / Math.abs(cur)).toFixed(1) : null;
    return { field: f, current: isFinite(cur) ? cur : snap[f], proposed: clean[f], change_pct: pct };
});
msg.payload = rows;
// The dashboard ui-text widget renders msg.payload only (its `format` property is
// ignored in this version), so the diagnosis goes out as its own payload string.
const diag = [proposal.diagnosis,
    'confidence: ' + proposal.confidence,
    proposal.expected_effect ? 'expected: ' + proposal.expected_effect : null,
    proposal.watch_for ? 'watch for: ' + proposal.watch_for : null
].filter(Boolean).join('<br><br>');
return [msg, { payload: diag }, null, null];

// Apply: GET /pid gave us the authoritative pre-apply state, stash it as the
// revert target, then hand the validated subset to POST /pid.
const cfg = flow.get('cfg');
const note = t => ({ payload: 'apply: ' + t });
if (!cfg) return [null, note('CONFIG has not run: redeploy the flow')];

const prop = flow.get('proposal') || {};
if (!prop.accepted) return [null, note('no accepted proposal to apply')];
if (typeof msg.payload !== 'object' || msg.payload === null || typeof msg.payload.kp !== 'number')
    return [null, note('GET /pid before apply returned no parameters')];
// One proposal, one apply: a second click must not re-post stale values.
if (flow.get('appliedProposalAt') === prop.at) return [null, note('this proposal was already applied')];

flow.set('lastgood', msg.payload);
if (cfg.dryRun) {
    flow.set('appliedProposalAt', prop.at);
    return [null, { payload: 'DRY RUN: would POST ' + JSON.stringify(prop.clean) }];
}

flow.set('appliedProposalAt', prop.at);
msg.payload = prop.clean;
msg.headers = { 'Content-Type': 'application/json' };
msg.action = 'apply';
return [msg, null];

// Post-POST bookkeeping for both apply and revert: confirm the device took the
// values, arm (or clear) the watchdog, and emit an audit record.
const cfg = flow.get('cfg');
const say = t => ({ payload: 'apply: ' + t });
if (!cfg) return [null, say('CONFIG has not run: redeploy the flow')];

const now = Date.now();
const isRevert = msg.action === 'revert';
const before = flow.get('lastgood') || {};
const after = msg.payload || {};
if (after.error) return [null, say('POST /pid failed: ' + after.error)];

const fields = ['kp', 'ki', 'kd', 'set_point', 'integral_limit', 'wind_down_threshold',
                'integral_unwind_factor', 'derivative_filter', 'output_min', 'output_max'];
const changed = [];
for (let i = 0; i < fields.length; i++) {
    const f = fields[i];
    if (typeof after[f] === 'number' && typeof before[f] === 'number' && after[f] !== before[f])
        changed.push(f + ' ' + before[f] + ' -> ' + after[f]);
}

const prop = flow.get('proposal') || {};
const refused = Object.keys(prop.clean || {}).filter(function (f) { return after[f] !== prop.clean[f]; });

const sp = typeof before.set_point === 'number' ? before.set_point : 0;
const win = (flow.get('buf') || []).filter(function (s) {
    return !s.fault && typeof s.temp === 'number' && s.received > now - cfg.windowMin * 60000;
});
let baseline = null;
if (win.length) {
    const e = win.map(function (s) { return s.temp - (typeof s.sp === 'number' ? s.sp : sp); });
    const bias = e.reduce(function (x, y) { return x + y; }, 0) / e.length;
    baseline = {
        n: win.length,
        bias: +bias.toFixed(2),
        mae: +(e.reduce(function (x, y) { return x + Math.abs(y); }, 0) / e.length).toFixed(2),
        satPct: +(100 * win.filter(function (s) { return s.saturated; }).length / win.length).toFixed(1)
    };
}

if (isRevert) {
    flow.set('applied', null);
} else {
    flow.set('applied', {
        ts: now,
        revertAfterMin: prop.revert_after_min > 0 ? prop.revert_after_min : cfg.revertAfterMin,
        before: before,
        baseline: baseline,
        clean: prop.clean || null
    });
}

const audit = {
    event: isRevert ? 'revert' : 'apply',
    at: new Date(now).toISOString(),
    reason: msg.reason || null,
    before: before, after: after,
    diagnosis: prop.diagnosis || null,
    confidence: prop.confidence || null,
    metrics: prop.metrics || null,
    model: cfg.llmModel
};
const log = flow.get('auditLog') || [];
log.push(audit);
flow.set('auditLog', log.slice(-50));

let text = (isRevert ? 'REVERTED' : 'APPLIED') + ': ' + (changed.length ? changed.join(', ') : 'no change');
if (!isRevert && refused.length) text += ' | device kept its old value for: ' + refused.join(', ');
if (!isRevert && baseline) text += ' | baseline mae ' + baseline.mae + ', bias ' + baseline.bias +
    ', sat ' + baseline.satPct + '% over ' + baseline.n + ' samples';

return [{ payload: audit, topic: 'tele/still2/tune' },
        { payload: text }];

// Manual revert to the snapshot captured just before the last apply.
const cfg = flow.get('cfg');
const note = t => ({ payload: 'revert: ' + t });
if (!cfg) return [null, note('CONFIG has not run: redeploy the flow')];

const lastgood = flow.get('lastgood');
if (!lastgood || typeof lastgood.kp !== 'number') return [null, note('nothing to revert to')];

const body = {};
['kp', 'ki', 'kd', 'set_point', 'output_min', 'output_max', 'integral_limit',
 'wind_down_threshold', 'integral_unwind_factor', 'derivative_filter'].forEach(function (f) {
    if (typeof lastgood[f] === 'number') body[f] = lastgood[f];
});

if (cfg.dryRun) return [null, note('DRY RUN - would POST ' + JSON.stringify(body))];

msg.payload = body;
msg.headers = { 'Content-Type': 'application/json' };
msg.action = 'revert';
msg.reason = 'manual';
return [msg, null];

// Watchdog: after `revertAfterMin` of running with the new gains, compare the
// window against the pre-apply baseline and revert if it got worse.
// Outputs: 1 = POST /pid, 2 = alert, 3 = dashboard status line.
const cfg = flow.get('cfg');
const note = t => ({ payload: t });
if (!cfg) return [null, null, null];

const applied = flow.get('applied');
if (!applied) return [null, null, note('idle - nothing applied')];

const now = Date.now();
const elapsedMin = (now - applied.ts) / 60000;
const base = applied.baseline || {};
const show = v => (typeof v === 'number' ? v.toFixed(2) : '-');
const head = 'armed ' + elapsedMin.toFixed(0) + '/' + applied.revertAfterMin + ' min';

const buf = (flow.get('buf') || []).filter(function (s) {
    return !s.fault && typeof s.temp === 'number' && s.received >= applied.ts;
});
if (buf.length < 5) return [null, null, note(head + ' - waiting for samples')];

const e = buf.map(function (s) { return s.temp - (typeof s.sp === 'number' ? s.sp : 0); });
const bias = e.reduce(function (x, y) { return x + y; }, 0) / e.length;
const mae = e.reduce(function (x, y) { return x + Math.abs(y); }, 0) / e.length;
const satPct = 100 * buf.filter(function (s) { return s.saturated; }).length / buf.length;
const status = head + ', mae ' + show(mae) + ' vs ' + show(base.mae) +
               ', bias ' + show(bias) + ' vs ' + show(base.bias);
if (elapsedMin < applied.revertAfterMin) return [null, null, note(status)];

const reasons = [];
if (base.mae > 0 && mae > base.mae * (1 + cfg.watchdogWorsePct / 100))
    reasons.push('mae ' + base.mae + ' -> ' + mae.toFixed(2));
if (Math.abs(bias) > Math.abs(base.bias || 0) + cfg.watchdogBiasMargin)
    reasons.push('bias ' + base.bias + ' -> ' + bias.toFixed(2));
if (satPct > cfg.watchdogSatPct) reasons.push('saturation ' + satPct.toFixed(0) + '%');
if (buf.some(function (s) { return s.pump_stalled; })) reasons.push('pump stall');

if (!reasons.length) {
    // Healthy for several horizons: stop watching this apply.
    if (elapsedMin > applied.revertAfterMin * 4) flow.set('applied', null);
    return [null, null, note('ok at the horizon: ' + status)];
}

flow.set('applied', null);
const text = 'watchdog revert after ' + elapsedMin.toFixed(0) + ' min: ' + reasons.join(', ');
if (cfg.dryRun) return [null, note('DRY RUN: ' + text), note(text)];

msg.payload = applied.before;
msg.headers = { 'Content-Type': 'application/json' };
msg.action = 'revert';
msg.reason = text;
return [msg, null, note(text)];
